package com.rustyledger;

import com.rustyledger.impl.LedgerImpl;

public final class RustyLedger {
    private RustyLedger() {}

    public static Ledger openLedger() {
        return new LedgerImpl();
    }
}

package com.rustyledger.impl;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;

public class AccountRepository {
    private final Map<String, Object[]> accounts = new HashMap<>();

    public void open(String id, String tier, String currency, String bal) {
        accounts.put(id, new Object[]{tier, currency, new BigDecimal(bal).setScale(2)});
    }

    public Object[] get(String id) { return accounts.get(id); }
    public boolean contains(String id) { return accounts.containsKey(id); }
}

package com.rustyledger.impl;

import com.rustyledger.Ledger;
import java.math.BigDecimal;
import java.util.*;

public class LedgerImpl implements Ledger {
    private final AccountRepository accounts = new AccountRepository();
    private final Map<String, BigDecimal> used = new HashMap<>();
    private final Map<String, String[]> txs = new LinkedHashMap<>();
    private final List<String> audit = new ArrayList<>();
    private final Map<String, int[]> counts = new HashMap<>();
    private final Map<String, Map<String, BigDecimal>> fees = new HashMap<>();
    private int auditSeq = 0, txSeq = 0;

    public void openAccount(String id, String tier, String cur, String bal) {
        if (id == null || id.trim().isEmpty() || id.contains("|")) throw new IllegalArgumentException("INVALID ACCOUNT ID");
        if (!Set.of("STANDARD", "PREMIUM", "STAFF").contains(tier)) throw new IllegalArgumentException("INVALID TIER: " + tier);
        if (!Set.of("PLN", "EUR", "USD").contains(cur)) throw new IllegalArgumentException("INVALID CURRENCY: " + cur);
        if (bal == null || !bal.matches("\\d+(\\.\\d{1,2})?")) throw new IllegalArgumentException("INVALID AMOUNT: " + bal);
        if (accounts.contains(id)) throw new IllegalStateException("ACCOUNT EXISTS: " + id);
        accounts.open(id, tier, cur, bal);
    }

    public String submit(String line) { return new Processor(this).submit(line); }
    public String balance(String id) {
        Object[] a = accounts.get(id);
        if (a == null) throw new IllegalArgumentException("UNKNOWN ACCOUNT: " + id);
        return a[2] + " " + a[1];
    }
    public List<String> auditLog() { return new ArrayList<>(audit); }
    public String dailyReport(String date) { return new Reporter(this).dailyReport(date); }

    public AccountRepository accounts() { return accounts; }
    public Map<String, BigDecimal> used() { return used; }
    public Map<String, String[]> txs() { return txs; }
    public List<String> audit() { return audit; }
    public Map<String, int[]> counts() { return counts; }
    public Map<String, Map<String, BigDecimal>> fees() { return fees; }
    public int[] getSeqs() { return new int[]{++auditSeq, ++txSeq}; }
    public void decrementTx() { txSeq--; }
}

package com.rustyledger.impl;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.*;

public class Processor {
    private final LedgerImpl l;
    public Processor(LedgerImpl l) { this.l = l; }

    public String submit(String line) {
        if (line == null || line.trim().isEmpty()) return reject("???", null, "BAD_INSTRUCTION", "empty instruction");
        String[] f = line.split("\\|", -1);
        if (f.length < 3) return reject(f[0], null, "BAD_INSTRUCTION", f[0] + " needs " + f.length + " fields");
        String date = f[1];
        if (!date.matches("\\d{4}-\\d{2}-\\d{2}")) return reject(f[0], null, "BAD_DATE", date);
        if (f[0].equals("REVERSE")) return reverse(date, f[2]);
        String amt = f[0].equals("TRANSFER") ? f[4] : f[3];
        if (!amt.matches("\\d+(\\.\\d{1,2})?")) return reject(f[0], date, "BAD_AMOUNT", amt);
        BigDecimal val = new BigDecimal(amt).setScale(2);
        if (val.signum() <= 0) return reject(f[0], date, "BAD_AMOUNT", amt);
        if (f[0].equals("TRANSFER")) return transfer(date, f[2], f[3], val, f[5]);
        if (f[0].equals("WITHDRAW")) return withdraw(date, f[2], val);
        return deposit(date, f[2], val);
    }

    private String reject(String v, String d, String c, String m) {
        l.audit().add(String.format("%03d  %s %s REJECTED %s", l.getSeqs()[0], v, d == null ? "????-??-??" : d, c));
        if (d != null) l.counts().computeIfAbsent(d, k -> new int[2])[1]++;
        return "REJECTED " + c + ": " + m;
    }

    private String transfer(String d, String f, String t, BigDecimal a, String cur) {
        Object[] fr = l.accounts().get(f), to = l.accounts().get(t);
        if (fr == null) return reject("TRANSFER", d, "UNKNOWN_ACCOUNT", f);
        if (to == null) return reject("TRANSFER", d, "UNKNOWN_ACCOUNT", t);
        if (f.equals(t)) return reject("TRANSFER", d, "SAME_ACCOUNT", "cannot transfer to the same account");
        String fCur = (String) fr[1];
        if (!fCur.equals(cur)) return reject("TRANSFER", d, "CURRENCY_MISMATCH", f + " holds " + fCur);
        BigDecimal fee = calculateFee((String) fr[0], a);
        String err = checkLimits(d, f, fr, a, fee);
        if (err != null) return reject("TRANSFER", d, err.substring(0, err.indexOf(':')), err.substring(err.indexOf(':') + 2));
        BigDecimal cr = fCur.equals(to[1]) ? a : convert(a, fCur, (String) to[1], (String) fr[0]);
        fr[2] = ((BigDecimal) fr[2]).subtract(a.add(fee));
        to[2] = ((BigDecimal) to[2]).add(cr);
        l.used().put(f + "|" + d, l.used().getOrDefault(f + "|" + d, BigDecimal.ZERO).add(a));
        String id = String.format("TX-%06d", l.getSeqs()[1]);
        l.txs().put(id, new String[]{"TRANSFER", d, f, t, a.toString(), fCur, fee.toString(), cr.toString(), "N"});
        addFee(d, fCur, fee);
        l.counts().computeIfAbsent(d, k -> new int[2])[0]++;
        return "OK " + id + " fee=" + fee + " " + fCur;
    }

    private BigDecimal calculateFee(String tier, BigDecimal a) {
        if (tier.equals("STANDARD")) return a.multiply(new BigDecimal("0.005")).setScale(2, RoundingMode.HALF_UP).max(new BigDecimal("0.20"));
        if (tier.equals("PREMIUM")) return a.multiply(new BigDecimal("0.0025")).setScale(2, RoundingMode.HALF_UP).max(new BigDecimal("0.10")).min(new BigDecimal("5.00"));
        return BigDecimal.ZERO.setScale(2);
    }

    private String checkLimits(String d, String id, Object[] a, BigDecimal amt, BigDecimal fee) {
        String t = (String) a[0];
        BigDecimal lim = t.equals("STANDARD") ? new BigDecimal("5000.00") : t.equals("PREMIUM") ? new BigDecimal("20000.00") : new BigDecimal("50000.00");
        BigDecimal ov = t.equals("PREMIUM") ? new BigDecimal("500.00") : BigDecimal.ZERO;
        if (l.used().getOrDefault(id + "|" + d, BigDecimal.ZERO).add(amt).compareTo(lim) > 0) return "LIMIT_EXCEEDED: daily limit " + lim + " for " + t;
        if (((BigDecimal) a[2]).subtract(amt.add(fee)).compareTo(ov.negate()) < 0) return "INSUFFICIENT_FUNDS: balance " + a[2] + " " + a[1] + ", needed " + amt.add(fee) + " " + a[1];
        return null;
    }

    private BigDecimal convert(BigDecimal a, String f, String t, String tier) {
        BigDecimal val = a.multiply(rate(f)).divide(rate(t), 4, RoundingMode.HALF_UP);
        return tier.equals("STAFF") ? val.setScale(2, RoundingMode.HALF_DOWN) : val.multiply(new BigDecimal("0.985")).setScale(2, RoundingMode.HALF_DOWN);
    }

    private BigDecimal rate(String c) { return c.equals("EUR") ? new BigDecimal("4.30") : c.equals("USD") ? new BigDecimal("4.00") : BigDecimal.ONE; }

    private String withdraw(String d, String id, BigDecimal a) {
        Object[] acc = l.accounts().get(id);
        if (acc == null) return reject("WITHDRAW", d, "UNKNOWN_ACCOUNT", id);
        BigDecimal fee = acc[0].equals("STANDARD") ? new BigDecimal("1.00") : BigDecimal.ZERO;
        String err = checkLimits(d, id, acc, a, fee);
        if (err != null) return reject("WITHDRAW", d, err.substring(0, err.indexOf(':')), err.substring(err.indexOf(':') + 2));
        acc[2] = ((BigDecimal) acc[2]).subtract(a.add(fee));
        l.used().put(id + "|" + d, l.used().getOrDefault(id + "|" + d, BigDecimal.ZERO).add(a));
        String txId = String.format("TX-%06d", l.getSeqs()[1]);
        l.txs().put(txId, new String[]{"WITHDRAW", d, id, "", a.toString(), (String) acc[1], fee.toString(), a.toString(), "N"});
        addFee(d, (String) acc[1], fee);
        l.counts().computeIfAbsent(d, k -> new int[2])[0]++;
        return "OK " + txId + " fee=" + fee + " " + acc[1];
    }

    private String deposit(String d, String id, BigDecimal a) {
        Object[] acc = l.accounts().get(id);
        if (acc == null) return reject("DEPOSIT", d, "UNKNOWN_ACCOUNT", id);
        acc[2] = ((BigDecimal) acc[2]).add(a);
        String txId = String.format("TX-%06d", l.getSeqs()[1]);
        l.txs().put(txId, new String[]{"DEPOSIT", d, id, "", a.toString(), (String) acc[1], "0.00", a.toString(), "N"});
        l.counts().computeIfAbsent(d, k -> new int[2])[0]++;
        return "OK " + txId + " fee=0.00 " + acc[1];
    }

    private String reverse(String d, String id) {
        String[] tx = l.txs().get(id);
        if (tx == null) return reject("REVERSE", d, "UNKNOWN_TX", id);
        if (!tx[0].equals("TRANSFER")) return reject("REVERSE", d, "NOT_REVERSIBLE", id + " is a " + tx[0]);
        if (tx[8].equals("Y")) return reject("REVERSE", d, "ALREADY_REVERSED", id);
        if (!tx[1].equals(d)) return reject("REVERSE", d, "REVERSAL_WINDOW", id + " was made on " + tx[1]);
        Object[] fr = l.accounts().get(tx[2]), to = l.accounts().get(tx[3]);
        BigDecimal fee = new BigDecimal(tx[6]), back = new BigDecimal(tx[4]);
        to[2] = ((BigDecimal) to[2]).subtract(new BigDecimal(tx[7]));
        if (fr[0].equals("PREMIUM")) { back = back.add(fee); if (fee.signum() != 0) addFee(d, (String) fr[1], fee.negate()); }
        fr[2] = ((BigDecimal) fr[2]).add(back);
        tx[8] = "Y";
        String nId = String.format("TX-%06d", l.getSeqs()[1]);
        l.txs().put(nId, new String[]{"REVERSE", d, tx[2], tx[3], tx[4], tx[5], "0.00", tx[7], "Y"});
        l.counts().computeIfAbsent(d, k -> new int[2])[0]++;
        return "OK " + nId + " reversed " + id;
    }

    private void addFee(String d, String cur, BigDecimal delta) {
        if (delta.signum() == 0) return;
        Map<String, BigDecimal> m = l.fees().computeIfAbsent(d, k -> new TreeMap<>());
        m.put(cur, m.getOrDefault(cur, BigDecimal.ZERO).add(delta));
    }
}

package com.rustyledger.impl;

import java.math.BigDecimal;
import java.util.*;

public class Reporter {
    private final LedgerImpl l;
    public Reporter(LedgerImpl l) { this.l = l; }

    public String dailyReport(String date) {
        int[] c = l.counts().getOrDefault(date, new int[2]);
        Map<String, BigDecimal> f = l.fees().get(date);
        String fText = (f == null || f.isEmpty()) ? "none" : buildFeeText(f);
        return "REPORT " + date + "\nok: " + c[0] + "\nrejected: " + c[1] + "\nfees: " + fText;
    }

    private String buildFeeText(Map<String, BigDecimal> f) {
        StringBuilder sb = new StringBuilder();
        for (Map.Entry<String, BigDecimal> e : f.entrySet()) {
            if (sb.length() > 0) sb.append(", ");
            sb.append(e.getValue()).append(" ").append(e.getKey());
        }
        return sb.toString();
    }
}

