package com.rustyledger.impl;
import java.math.BigDecimal;
import java.math.RoundingMode;
public class TransferOp {
    private final LedgerImpl l;
    public TransferOp(LedgerImpl l) { this.l = l; }
    public String exec(String d, String f, String t, BigDecimal a, String cur) {
        Object[] fr = l.accounts().get(f), to = l.accounts().get(t);
        if (fr == null) return new Processor(l).reject("TRANSFER", d, "UNKNOWN_ACCOUNT", f);
        if (to == null) return new Processor(l).reject("TRANSFER", d, "UNKNOWN_ACCOUNT", t);
        if (f.equals(t)) return new Processor(l).reject("TRANSFER", d, "SAME_ACCOUNT", "cannot transfer to the same account");
        String fCur = (String) fr[1];
        if (!fCur.equals(cur)) return new Processor(l).reject("TRANSFER", d, "CURRENCY_MISMATCH", f + " holds " + fCur);
        BigDecimal fee = calculateFee((String) fr[0], a);
        String err = checkLimits(d, f, fr, a, fee);
        if (err != null) return new Processor(l).reject("TRANSFER", d, err.split(":")[0], err.substring(err.indexOf(':') + 2));
        BigDecimal cr = fCur.equals(to[1]) ? a : convert(a, fCur, (String) to[1], (String) fr[0]);
        fr[2] = ((BigDecimal) fr[2]).subtract(a.add(fee));
        to[2] = ((BigDecimal) to[2]).add(cr);
        l.used().put(f + "|" + d, l.used().getOrDefault(f + "|" + d, BigDecimal.ZERO).add(a));
        String id = String.format("TX-%06d", l.nextTx());
        l.txs().put(id, new String[]{"TRANSFER", d, f, t, a.toString(), fCur, fee.toString(), cr.toString(), "N"});
        addFee(d, fCur, fee);
        l.counts().computeIfAbsent(d, k -> new int[2])[0]++;
        return "OK " + id + " fee=" + fee + " " + fCur;
    }
    private BigDecimal calculateFee(String tier, BigDecimal a) {
        if (tier.equals("STANDARD")) return a.multiply(new BigDecimal("0.005")).setScale(2, RoundingMode.HALF_UP).max(new BigDecimal("0.20"));
        if (tier.equals("PREMIUM")) return a.multiply(new BigDecimal("0.0025")).setScale(2, RoundingMode.HALF_UP).max(new BigDecimal("0.10")).min(new BigDecimal("5.00"));
        return new BigDecimal("0.00");
    }
    private String checkLimits(String d, String id, Object[] a, BigDecimal amt, BigDecimal fee) {
        String t = (String) a[0];
        BigDecimal lim = t.equals("STANDARD") ? new BigDecimal("5000.00") : t.equals("PREMIUM") ? new BigDecimal("20000.00") : new BigDecimal("50000.00");
        BigDecimal ov = t.equals("PREMIUM") ? new BigDecimal("500.00") : BigDecimal.ZERO;
        if (l.used().getOrDefault(id + "|" + d, BigDecimal.ZERO).add(amt).compareTo(lim) > 0) return "LIMIT_EXCEEDED: daily limit " + lim + " for " + t;
        if (((BigDecimal) a[2]).subtract(amt.add(fee)).compareTo(ov.negate()) < 0) return "INSUFFICIENT_FUNDS: balance " + a[2] + " " + a[1] + ", needed " + amt.add(fee) + " " + a[1];
        return null;
    }
    private BigDecimal convert(BigDecimal a, String f, String t, String tier) {
        BigDecimal val = a.multiply(rate(f)).divide(rate(t), 4, RoundingMode.HALF_UP);
        return tier.equals("STAFF") ? val.setScale(2, RoundingMode.HALF_DOWN) : val.multiply(new BigDecimal("0.985")).setScale(2, RoundingMode.HALF_DOWN);
    }
    private BigDecimal rate(String c) { return c.equals("EUR") ? new BigDecimal("4.30") : c.equals("USD") ? new BigDecimal("4.00") : BigDecimal.ONE; }
    private void addFee(String d, String cur, BigDecimal delta) {
        if (delta.signum() == 0) return;
        Map<String, BigDecimal> m = l.fees().computeIfAbsent(d, k -> new TreeMap<>());
        m.put(cur, m.getOrDefault(cur, BigDecimal.ZERO).add(delta));
    }
}

